/* static/css/style.css */

/* General Reset */
body, h1, h2, h3, h4, h5, h6, p, ul, ol, li, a, button {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

/* Body Styling */
body {
    font-family: 'Arial', sans-serif;
    line-height: 1.6;
    background-color: #f4f4f9;
    color: #333;
    padding: 0;
    margin: 0;
}

/* Header */
header {
    background: #333;
    color: #fff;
    padding: 1rem 2rem;
    text-align: center;
}

header h1 {
    font-size: 2.5rem;
    margin-bottom: 0.5rem;
}

header nav {
    margin-top: 1rem;
}

header nav a {
    color: #fff;
    margin: 0 1rem;
    text-decoration: none;
    font-weight: bold;
}

header nav a:hover {
    color: #ff6347;
}

/* Main Section */
main {
    padding: 2rem;
}

/* Buttons */
button {
    background-color: #ff6347;
    color: white;
    border: none;
    padding: 0.5rem 1rem;
    cursor: pointer;
    border-radius: 5px;
    font-size: 1rem;
}

button:hover {
    background-color: #e5533f;
}

/* Forms */
form {
    margin: 2rem 0;
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

form input, 
form textarea {
    padding: 0.5rem;
    font-size: 1rem;
    border: 1px solid #ccc;
    border-radius: 5px;
    width: 100%;
}

form input:focus, 
form textarea:focus {
    outline: none;
    border-color: #333;
}

/* Problem Cards */
.problem-card {
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 5px;
    padding: 1rem;
    margin-bottom: 1rem;
    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
}

.problem-card h2 {
    font-size: 1.5rem;
    color: #333;
}

.problem-card p {
    margin: 0.5rem 0;
    color: #666;
}

/* Footer */
footer {
    background: #333;
    color: #fff;
    text-align: center;
    padding: 1rem;
    margin-top: 2rem;
}

footer p {
    font-size: 0.9rem;
}

footer a {
    color: #ff6347;
    text-decoration: none;
}

footer a:hover {
    text-decoration: underline;
}

// static/js/app.js
// Purpose: Frontend JavaScript code for the ACM Problem-Solving Platform

// Function to handle navigation between tabs
function switchTab(tabId) {
    const tabs = document.querySelectorAll('.tab-content');
    tabs.forEach(tab => {
        tab.style.display = 'none';
    });
    document.getElementById(tabId).style.display = 'block';
}

// Function to submit a solution
async function submitSolution(problemId) {
    const codeEditor = document.getElementById('code-editor');
    const solutionCode = codeEditor.value;

    const response = await fetch(`/api/submit/${problemId}`, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({ code: solutionCode }),
    });

    const result = await response.json();
    if (result.success) {
        alert('Solution submitted successfully!');
        window.location.href = '/leaderboard'; // Redirect to leaderboard
    } else {
        alert(`Error: ${result.error}`);
    }
}

// Function to fetch and display problem details
async function loadProblem(problemId) {
    const response = await fetch(`/api/problem/${problemId}`);
    const data = await response.json();

    if (data.success) {
        document.getElementById('problem-title').innerText = data.problem.title;
        document.getElementById('problem-description').innerText = data.problem.description;
    } else {
        alert(`Error fetching problem details: ${data.error}`);
    }
}

// Function to initialize the code editor
function initializeCodeEditor() {
    const editor = document.getElementById('code-editor');
    editor.value = '// Write your code here...\n';
}

// Event listeners for interactive elements
document.addEventListener('DOMContentLoaded', () => {
    initializeCodeEditor();

    const submitButton = document.getElementById('submit-button');
    if (submitButton) {
        submitButton.addEventListener('click', () => {
            const problemId = submitButton.getAttribute('data-problem-id');
            submitSolution(problemId);
        });
    }

    const navLinks = document.querySelectorAll('.nav-link');
    navLinks.forEach(link => {
        link.addEventListener('click', (event) => {
            event.preventDefault();
            const tabId = link.getAttribute('data-tab');
            switchTab(tabId);
        });
    });
});

from flask import Blueprint, render_template, request, redirect, url_for, flash
from app.models.problem import Problem
from app.database import db

problem_bp = Blueprint('problem', __name__)

@problem_bp.route('/problems', methods=['GET'])
def list_problems():
    try:
        problems = Problem.query.all()
        return render_template('problem.html', problems=problems)
    except Exception as e:
        flash(f"Error loading problems: {str(e)}", "danger")
        return redirect(url_for('index'))

@problem_bp.route('/problem/<int:problem_id>', methods=['GET'])
def view_problem(problem_id):
    try:
        problem = Problem.query.get(problem_id)
        if not problem:
            flash("Problem not found", "danger")
            return redirect(url_for('list_problems'))
        return render_template('problem.html', problem=problem)
    except Exception as e:
        flash(f"Error loading problem: {str(e)}", "danger")
        return redirect(url_for('list_problems'))

@problem_bp.route('/problem/new', methods=['GET', 'POST'])
def create_problem():
    if request.method == 'POST':
        title = request.form.get('title')
        description = request.form.get('description')
        difficulty = request.form.get('difficulty')
        try:
            new_problem = Problem(title=title, description=description, difficulty=difficulty)
            db.session.add(new_problem)
            db.session.commit()
            flash("Problem created successfully", "success")
            return redirect(url_for('list_problems'))
        except Exception as e:
            flash(f"Error creating problem: {str(e)}", "danger")
            return redirect(url_for('create_problem'))
    return render_template('submit.html')

@problem_bp.route('/problem/<int:problem_id>/edit', methods=['GET', 'POST'])
def edit_problem(problem_id):
    problem = Problem.query.get(problem_id)
    if not problem:
        flash("Problem not found", "danger")
        return redirect(url_for('list_problems'))
    if request.method == 'POST':
        problem.title = request.form.get('title')
        problem.description = request.form.get('description')
        problem.difficulty = request.form.get('difficulty')
        try:
            db.session.commit()
            flash("Problem updated successfully", "success")
            return redirect(url_for('view_problem', problem_id=problem.id))
        except Exception as e:
            flash(f"Error updating problem: {str(e)}", "danger")
            return redirect(url_for('edit_problem', problem_id=problem.id))
    return render_template('submit.html', problem=problem)

@problem_bp.route('/problem/<int:problem_id>/delete', methods=['POST'])
def delete_problem(problem_id):
    problem = Problem.query.get(problem_id)
    if not problem:
        flash("Problem not found", "danger")
        return redirect(url_for('list_problems'))
    try:
        db.session.delete(problem)
        db.session.commit()
        flash("Problem deleted successfully", "success")
        return redirect(url_for('list_problems'))
    except Exception as e:
        flash(f"Error deleting problem: {str(e)}", "danger")
        return redirect(url_for('list_problems'))

from flask import Blueprint, request, jsonify, render_template, redirect, url_for
from app.database import db
from app.models.user import User

user_bp = Blueprint('user', __name__)

@user_bp.route('/users', methods=['GET'])
def list_users():
    """Retrieve a list of all users."""
    try:
        users = User.query.all()
        user_list = [{"id": user.id, "username": user.username, "email": user.email} for user in users]
        return jsonify(user_list), 200
    except Exception as e:
        return jsonify({"error": str(e)}), 500

@user_bp.route('/user/<int:user_id>', methods=['GET'])
def view_user(user_id):
    """Retrieve details of a specific user."""
    try:
        user = User.query.get(user_id)
        if not user:
            return jsonify({"error": "User not found"}), 404
        user_data = {"id": user.id, "username": user.username, "email": user.email}
        return jsonify(user_data), 200
    except Exception as e:
        return jsonify({"error": str(e)}), 500

@user_bp.route('/user/new', methods=['POST'])
def create_user():
    """Create a new user."""
    try:
        data = request.json
        username = data.get('username')
        email = data.get('email')
        if not username or not email:
            return jsonify({"error": "Missing required fields"}), 400
        new_user = User(username=username, email=email)
        db.session.add(new_user)
        db.session.commit()
        return jsonify({"message": "User created successfully", "user_id": new_user.id}), 201
    except Exception as e:
        return jsonify({"error": str(e)}), 500

@user_bp.route('/user/<int:user_id>/edit', methods=['PUT'])
def edit_user(user_id):
    """Edit an existing user's information."""
    try:
        user = User.query.get(user_id)
        if not user:
            return jsonify({"error": "User not found"}), 404
        data = request.json
        user.username = data.get('username', user.username)
        user.email = data.get('email', user.email)
        db.session.commit()
        return jsonify({"message": "User updated successfully"}), 200
    except Exception as e:
        return jsonify({"error": str(e)}), 500

@user_bp.route('/user/<int:user_id>/delete', methods=['DELETE'])
def delete_user(user_id):
    """Delete a user."""
    try:
        user = User.query.get(user_id)
        if not user:
            return jsonify({"error": "User not found"}), 404
        db.session.delete(user)
        db.session.commit()
        return jsonify({"message": "User deleted successfully"}), 200
    except Exception as e:
        return jsonify({"error": str(e)}), 500
